CREATE TABLE IF NOT EXISTS lgas (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    code VARCHAR(10) NOT NULL,
    state_id INTEGER NOT NULL REFERENCES c_states(id) ON DELETE CASCADE,
    state_name VARCHAR(255) NOT NULL,
    senatorial_district_id INTEGER REFERENCES senatorial_districts(id) ON DELETE CASCADE,
    senatorial_district_name VARCHAR(255),
    federal_constituency_id INTEGER REFERENCES federal_constituencies(id) ON DELETE CASCADE,
    federal_constituency_name VARCHAR(255),
    state_constituencies_count INTEGER DEFAULT 0,
    wards_count INTEGER DEFAULT 0,
    polling_units_count INTEGER DEFAULT 0,
    mongo_id VARCHAR(50),
    status VARCHAR(50) DEFAULT 'active'
);

CREATE INDEX idx_lgas_state_id_name ON lgas (state_id, name);
CREATE INDEX idx_lgas_senatorial_district_id ON lgas (senatorial_district_id);
CREATE INDEX idx_lgas_federal_constituency_id ON lgas (federal_constituency_id);

-- SEED DATA START
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, code = EXCLUDED.code, state_id = EXCLUDED.state_id, state_name = EXCLUDED.state_name, senatorial_district_id = EXCLUDED.senatorial_district_id, senatorial_district_name = EXCLUDED.senatorial_district_name, federal_constituency_id = EXCLUDED.federal_constituency_id, federal_constituency_name = EXCLUDED.federal_constituency_name, status = EXCLUDED.status, mongo_id = COALESCE(NULLIF(EXCLUDED.mongo_id, ''), lgas.mongo_id);
-- SEED DATA END

-- +goose Down
DROP INDEX IF EXISTS idx_lgas_state_id_name;
DROP TABLE IF EXISTS lgas;